var (
	testmsg1 = hexutil.MustDecode("0x68692074686572656f636b636861696e62626262626262626262626262626262")
	testmsg2 = hexutil.MustDecode("0x68692074686572656f636b636861696e62626262626262626262626262626261")
)

func testHybridEddsaMldsaSlhdsaSigBasic(t *testing.T) {
	var sig signaturealgorithm.SignatureAlgorithm
	sig = CreateHybridEddsaMldsaSlhdsaSig5()
	signaturealgorithm.SignatureAlgorithmTest(t, sig)
}

func TestHybridEddsaMldsaSlhdsaSig_Basic(t *testing.T) {
	fmt.Println("TestHybridEddsaMldsaSlhdsaSig_Basic")
	testHybridEddsaMldsaSlhdsaSigBasic(t)
}

func TestHybridEddsaMldsaSlhdsaSeed(t *testing.T) {
	var seed [hybridedmldsaslhdsa5.SeedSize]byte
	for i := byte(0); i < hybridedmldsaslhdsa5.SeedSize; i++ {
		seed[i] = i
	}

	sig := CreateHybridEddsaMldsaSlhdsaSig5()
	pKey, err := sig.GenerateKeyWithSeed(seed[:])
	if err != nil {
		t.Fatal("failed")
	}

	sigb, _ := sig.Sign(testmsg1, pKey)

	fmt.Println(base64.StdEncoding.EncodeToString(pKey.PubData))
	fmt.Println(base64.StdEncoding.EncodeToString(sigb))

	addr := crypto.PublicKeyBytesToAddress(pKey.PubData)
	expected := common.HexToAddress("0xd846075401c4E3e67d1F5aC5df389fc722197f0cdE37aB73A8005d801df513b3")
	if addr.IsEqualTo(expected) == false {
		t.Fatal("failed address check")
	}
}

func testBase64(t *testing.T) {
	var sig signaturealgorithm.SignatureAlgorithm
	sig = CreateHybridEddsaMldsaSlhdsaSig5()

	serverSigningPublicKey := ""
	signature := ""

	serverSigningPublicKeyBytes, err := base64.StdEncoding.DecodeString(serverSigningPublicKey)
	if err != nil {
		t.Fatalf("failed")
	}
	signatureBytes, err := base64.StdEncoding.DecodeString(signature)
	if err != nil {
		t.Fatalf("failed")
	}
	fmt.Println("signatureBytes", len(signatureBytes))

	pubKeyExpected, err := sig.DecodePublicKey(serverSigningPublicKeyBytes)
	if err != nil {
		t.Fatalf("failed")
	}
	addressActual, err := sig.PublicKeyToAddress(pubKeyExpected)
	if err != nil {
		t.Fatalf("failed")
	}
	addressExpected := common.HexToAddress("0xd846075401c4E3e67d1F5aC5df389fc722197f0cdE37aB73A8005d801df513b3")
	if addressActual.IsEqualTo(addressExpected) == false {
		t.Fatal("failed address check")
	}

	_, pubE, err := sig.PublicKeyAndSignatureFromCombinedSignature(testmsg1, signatureBytes)
	if err != nil {
		t.Fatalf("failed")
	}
	pub2, err := sig.DecodePublicKey(pubE)
	if err != nil {
		t.Fatalf("failed")
	}
	address2, err := sig.PublicKeyToAddress(pub2)
	if err != nil {
		t.Fatalf("failed")
	}
	if address2.IsEqualTo(addressExpected) == false {
		t.Fatal("failed address check")
	}

	fmt.Println("addressExpected", "aa", "addressActual", addressActual)
}

func TestGenerateKeyFromPreExpansionSeed(t *testing.T) {
	var preExpansionSeed [hybridedmldsaslhdsa5.BaseSeedSize]byte
	for i := 0; i < hybridedmldsaslhdsa5.BaseSeedSize; i++ {
		preExpansionSeed[i] = byte(i)
	}

	sig := CreateHybridEddsaMldsaSlhdsaSig5()
	pKey, err := sig.GenerateKeyFromPreExpansionSeed(preExpansionSeed[:])
	if err != nil {
		t.Fatal("GenerateKeyFromPreExpansionSeed failed:", err)
	}
	if pKey == nil || len(pKey.PriData) == 0 || len(pKey.PubData) == 0 {
		t.Fatal("GenerateKeyFromPreExpansionSeed returned empty key")
	}

	addr := crypto.PublicKeyBytesToAddress(pKey.PubData)
	expected := common.HexToAddress("0x1C8A52094a8a94f87Bdc60d435e0603C3046611bb9C544B4CD154c8d7b75C4a8")
	if !addr.IsEqualTo(expected) {
		t.Fatalf("address mismatch: got %s, want %s", addr.Hex(), expected.Hex())
	}

	pKey2, err := sig.GenerateKeyFromPreExpansionSeed(preExpansionSeed[:])
	if err != nil {
		t.Fatal("second call failed:", err)
	}
	addr2 := crypto.PublicKeyBytesToAddress(pKey2.PubData)
	if !addr.IsEqualTo(addr2) {
		t.Fatal("deterministic generation produced different addresses")
	}
}

func TestGenerateKeyFromPreExpansionSeed_WrongSize(t *testing.T) {
	wrongSeed := make([]byte, 32)
	sig := CreateHybridEddsaMldsaSlhdsaSig5()
	_, err := sig.GenerateKeyFromPreExpansionSeed(wrongSeed)
	if err == nil {
		t.Fatal("expected error for wrong seed size")
	}
}

func TestBase64(t *testing.T) {
	testBase64(t)
}
